int from_filename(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i, j = 0;
    unsigned char c;

    for (i = 0; i < fromlen; i++) {
        c = from[i];
        if (c == '/') {
            if (j < tolen - 1) {
                to[j++] = '/';
            } else {
                return -ENAMETOOLONG;
            }
        } else if (c == '.') {
            if (i + 1 < fromlen && from[i + 1] == '/') {
                i++;
                if (j < tolen - 1) {
                    to[j++] = '.';
                    to[j++] = '.';
                } else {
                    return -ENAMETOOLONG;
                }
