int path_component_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0, j = 0;

    while (i < fromlen && j < tolen - 1) {
        unsigned char type = from[i];

        switch (type) {
            case 0: // symlink
                if (j + 2 > tolen - 1)
                    return -1;
                to[j++] = '.';
                to[j++] = '.';
                to[j++] = '/';
                break;
            case 1: // directory
                if (j + 2 > tolen - 1)
                    return -1;
                to[j++] = '.';
                to[j++] = '/';
                break;
            case 2: // file name
                while (i < fromlen && from[i] != 0) {
                    if (j >= tolen - 1)
                        return -1;
                    to[j++] = from[i++];
                }
                break;
            default:
                if (j >= tolen - 1)
                    return -1;
                to[j++] = from[i];
                break;
        }

        i++;
    }

    if (j >= tolen)
        return -1;

    to[j] = '\0';
    return 0;
}
